<?php
$labels = Ha_readiness::check_labels();
$pol = $edit_policy;
$prules = $pol ? (json_decode($pol['rules_json'], true) ?: array()) + Ha_readiness::default_rules() : Ha_readiness::default_rules();
$prog = $edit_program;
$gr = $prog ? json_decode($prog['rules_json'], true) : array();
$gr = (is_array($gr) ? $gr : array()) + array('tracks' => array(), 'rubrics' => array(), 'assessments' => array(), 'competencies' => array(), 'require_readiness' => 'ready');
$comp = array(); foreach ($gr['competencies'] as $c) { $comp[$c['skill_id']] = $c['level']; }
$asel = array_map(function ($a) { return (int) (is_array($a) ? $a['id'] : $a); }, $gr['assessments']);
?>
<div class="hkp-head"><div><h1><?php echo hkp_e('Readiness & certification rules'); ?></h1><p><?php echo hkp_e('Every rule is data, not code: change what makes someone Ready, and what a certificate requires, without a release.'); ?></p></div>
<div class="hkp-actions"><a class="hkp-btn" href="<?php echo hkp_url('admin/rules/policy'); ?>"><?php echo hkp_e('New policy'); ?></a><a class="hkp-btn hkp-btn--ghost" href="<?php echo hkp_url('admin/rules/program'); ?>"><?php echo hkp_e('New programme'); ?></a></div></div>
